// Parse lead data
const leadData = typeof $input.item.json.leadData === 'string' ? 
  JSON.parse($input.item.json.leadData) : $input.item.json.leadData;
const agentType = $input.item.json.agentType;
const priority = $input.item.json.priority;

// Define agent pool with availability simulation
const agents = {
  senior_booking_agent: [
    { id: 'SBA-001', name: 'Sarah Mitchell', email: 'sarah@sambora.com', expertise: ['luxury_bookings', 'group_travel'], available: true, currentLoad: 3 },
    { id: 'SBA-002', name: 'James Uwimana', email: 'james@sambora.com', expertise: ['luxury_bookings', 'permits'], available: true, currentLoad: 5 },
    { id: 'SBA-003', name: 'Patricia Kayitesi', email: 'patricia@sambora.com', expertise: ['vip_clients', 'custom_itineraries'], available: false, currentLoad: 8 }
  ],
  travel_planning_specialist: [
    { id: 'TPS-001', name: 'Michael Ngabo', email: 'michael@sambora.com', expertise: ['itinerary_planning', 'multi_destination'], available: true, currentLoad: 4 },
    { id: 'TPS-002', name: 'Grace Mukankusi', email: 'grace@sambora.com', expertise: ['first_time_visitors', 'budget_planning'], available: true, currentLoad: 2 },
    { id: 'TPS-003', name: 'David Habimana', email: 'david@sambora.com', expertise: ['adventure_travel', 'photography_tours'], available: true, currentLoad: 6 }
  ],
  customer_service: [
    { id: 'CS-001', name: 'Emma Mukamazimpaka', email: 'emma@sambora.com', expertise: ['general_inquiries', 'support'], available: true, currentLoad: 3 },
    { id: 'CS-002', name: 'Robert Nkusi', email: 'robert@sambora.com', expertise: ['modifications', 'special_requests'], available: true, currentLoad: 4 }
  ]
};

// Select best available agent
let selectedAgent = null;
const agentPool = agents[agentType] || agents.customer_service;

// Filter available agents and sort by current load
const availableAgents = agentPool
  .filter(agent => agent.available)
  .sort((a, b) => a.currentLoad - b.currentLoad);

if (availableAgents.length > 0) {
  // For high priority, select agent with specific expertise if available
  if (priority === 'high') {
    const expertAgent = availableAgents.find(a => 
      a.expertise.includes('luxury_bookings') || 
      a.expertise.includes('vip_clients')
    );
    selectedAgent = expertAgent || availableAgents[0];
  } else {
    // Select agent with lowest current load
    selectedAgent = availableAgents[0];
  }
} else {
  // No agents available - use round-robin or queue
  selectedAgent = {
    id: 'QUEUE-001',
    name: 'Next Available Agent',
    email: 'reservations@sambora.com',
    status: 'queued'
  };
}

return {
  json: {
    leadData,
    selectedAgent,
    agentType,
    priority,
    routingDetails: {
      routedAt: new Date().toISOString(),
      routingMethod: selectedAgent.status === 'queued' ? 'queue' : 'direct_assignment',
      estimatedResponseTime: priority === 'high' ? '1 hour' : '24 hours'
    }
  }
};

