=<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: linear-gradient(135deg, #2d5016 0%, #4a7c2c 100%); color: white; padding: 20px; border-radius: 8px 8px 0 0; }
    .content { background: #f9f9f9; padding: 20px; border: 1px solid #ddd; }
    .lead-info { background: white; padding: 15px; margin: 10px 0; border-left: 4px solid #4a7c2c; }
    .priority-badge { display: inline-block; padding: 5px 15px; border-radius: 20px; font-weight: bold; }
    .high { background: #dc3545; color: white; }
    .medium { background: #ffc107; color: #333; }
    .low { background: #6c757d; color: white; }
    .data-point { margin: 8px 0; }
    .label { font-weight: bold; color: #2d5016; }
    .cta-button { display: inline-block; padding: 12px 30px; background: #4a7c2c; color: white; text-decoration: none; border-radius: 5px; margin: 15px 0; }
    .conversation { background: #fff; padding: 15px; margin: 10px 0; max-height: 300px; overflow-y: auto; border: 1px solid #ddd; border-radius: 4px; }
    .message { margin: 10px 0; padding: 8px; border-radius: 4px; }
    .user-message { background: #e3f2fd; }
    .bot-message { background: #f1f8e9; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🦍 New Lead Alert - Sambora Kinigi</h1>
      <p>You've been assigned a new inquiry</p>
    </div>

    <div class="content">
      <div class="lead-info">
        <h2>Lead Information</h2>
        <span class="priority-badge {{ $json.priority }}">{{ $json.priority.toUpperCase() }} PRIORITY</span>

        <div class="data-point">
          <span class="label">Lead Score:</span> {{ $json.leadData.leadScore }}/100
        </div>
        <div class="data-point">
          <span class="label">Guest Name:</span> {{ $json.leadData.userName }}
        </div>
        <div class="data-point">
          <span class="label">Session ID:</span> {{ $json.leadData.sessionId }}
        </div>
        <div class="data-point">
          <span class="label">Qualified At:</span> {{ $json.leadData.qualifiedAt }}
        </div>
      </div>

      <div class="lead-info">
        <h3>📋 Extracted Information</h3>
        {{ $json.leadData.extractedData.dates ? '<div class="data-point"><span class="label">Travel Dates:</span> ' + $json.leadData.extractedData.dates + '</div>' : '' }}
        {{ $json.leadData.extractedData.groupSize ? '<div class="data-point"><span class="label">Group Size:</span> ' + $json.leadData.extractedData.groupSize + ' people</div>' : '' }}
        {{ $json.leadData.extractedData.email ? '<div class="data-point"><span class="label">Email:</span> ' + $json.leadData.extractedData.email + '</div>' : '' }}
        {{ $json.leadData.extractedData.phone ? '<div class="data-point"><span class="label">Phone:</span> ' + $json.leadData.extractedData.phone + '</div>' : '' }}
        {{ $json.leadData.extractedData.trekInterest ? '<div class="data-point"><span class="label">Trek Interest:</span> Yes ✅</div>' : '' }}
        {{ $json.leadData.extractedData.specialRequests && $json.leadData.extractedData.specialRequests.length > 0 ? '<div class="data-point"><span class="label">Special Requests:</span> ' + $json.leadData.extractedData.specialRequests.join(', ') + '</div>' : '' }}
      </div>

      <div class="lead-info">
        <h3>🎯 Detected Intents</h3>
        {{ $json.leadData.intents.booking ? '✅ Ready to book<br>' : '' }}
        {{ $json.leadData.intents.pricing ? '✅ Interested in pricing<br>' : '' }}
        {{ $json.leadData.intents.permits ? '✅ Asking about permits<br>' : '' }}
        {{ $json.leadData.intents.dates ? '✅ Discussing dates<br>' : '' }}
        {{ $json.leadData.intents.contact ? '✅ Requested contact<br>' : '' }}
      </div>

      <div class="conversation">
        <h3>💬 Conversation Summary</h3>
        {{ $json.leadData.conversationHistory.slice(-10).map(msg => 
          '<div class="message ' + (msg.role === 'user' ? 'user-message' : 'bot-message') + '">' +
          '<strong>' + (msg.role === 'user' ? 'Guest' : 'Chatbot') + ':</strong> ' +
          msg.content +
          '</div>'
        ).join('') }}
      </div>

      <div class="lead-info">
        <h3>⚡ Recommended Next Steps</h3>
        <ul>
          {{ $json.leadData.extractedData.email ? '<li>Send personalized follow-up email within ' + $json.routingDetails.estimatedResponseTime + '</li>' : '<li>Contact guest to collect email address</li>' }}
          {{ $json.leadData.extractedData.dates ? '<li>Check availability for requested dates</li>' : '<li>Propose date options</li>' }}
          {{ $json.leadData.intents.permits ? '<li>Initiate permit booking process</li>' : '' }}
          {{ $json.leadData.extractedData.groupSize ? '<li>Prepare group booking quote</li>' : '' }}
          <li>Provide detailed itinerary options</li>
          <li>Answer any outstanding questions from conversation</li>
        </ul>
      </div>

      <center>
        <a href="#" class="cta-button">View Full Lead Details</a>
      </center>

      <div style="margin-top: 20px; padding: 15px; background: #fff3cd; border-left: 4px solid #ffc107; border-radius: 4px;">
        <strong>⏰ Expected Response Time:</strong> {{ $json.routingDetails.estimatedResponseTime }}<br>
        <strong>📊 Data Completeness:</strong> {{ $json.leadData.dataCompleteness.completenessPercentage }}%
      </div>
    </div>

    <div style="margin-top: 20px; text-align: center; color: #666; font-size: 12px;">
      <p>This lead was automatically qualified and routed by the Sambora AI Inquiry Management System</p>
      <p>Routed at: {{ $json.routingDetails.routedAt }}</p>
    </div>
  </div>
</body>
</html>

